<script>
  import { rpc, day, color } from "../lib/api.js"; import { go } from "../lib/router.svelte.js";
  let { id } = $props(); let e = $state(null), err = $state("");
  $effect(() => { rpc("entity", { id }).then((r) => (e = r)).catch((x) => (err = x.message)); });
</script>
{#if err}<p class="text-sm text-dim">{err}</p>{:else if !e}<p class="text-sm text-dim">loading</p>{:else}
<article class="space-y-5">
  <header><div class="flex items-center gap-2"><span class="h-3 w-3 rounded-full" style="background:{color(e.top)}"></span><h1 class="text-xl font-semibold">{e.label}</h1></div>
    <p class="text-sm text-dim">{e.top} · {#each e.kinds as k, i}{i ? ", " : ""}<a href={"/prototypes/" + encodeURIComponent(k.prototype)} class="hover:text-brand" title={"score " + k.score.toFixed(2) + " · " + k.rank}>{k.label}</a>{/each}{#if e.aliases.length} · also {e.aliases.join(", ")}{/if}</p>
    {#if e.description}<p class="mt-2 text-sm leading-6">{e.description}</p>{/if}
    <div class="mt-2 flex flex-wrap gap-1 text-[11px]"><span class="chip num">{e.mentions} mentions</span><span class="chip num">seen {day(e.firstSeen)} → {day(e.lastSeen)}</span>{#if e.location}<a class="chip" href={"/?e=" + encodeURIComponent(e.id)}>on the map · {e.location.method === "wikidata" ? "gazetteer" : "approximate"} ±{Math.round(e.location.rad / 1000)} km</a>{/if}<a class="chip" href={"/graph?e=" + encodeURIComponent(e.id)}>in the graph</a>{#if e.identity?.wikidata}<a class="chip" href={"https://www.wikidata.org/wiki/" + e.identity.wikidata} target="_blank" rel="noopener">wikidata {e.identity.wikidata}</a>{/if}{#if e.identity?.wikipedia}<a class="chip" href={e.identity.wikipedia} target="_blank" rel="noopener">wikipedia</a>{/if}</div>
  </header>
  <section><h2 class="mb-1 text-xs font-semibold uppercase tracking-wide text-dim">Components</h2><div class="grid gap-2 sm:grid-cols-2">{#each Object.entries(e.components) as [name, c]}<div class="rounded-[4px] bg-panel p-2 text-xs"><div class="num mb-1 font-semibold">{name}</div><pre class="whitespace-pre-wrap break-words text-[11px] text-dim">{JSON.stringify(c, null, 1).replace(/[{}"]/g, "").trim()}</pre></div>{/each}</div></section>
  {#if e.relations.length}<section><h2 class="mb-1 text-xs font-semibold uppercase tracking-wide text-dim">Relations</h2><ul class="space-y-1 text-sm">{#each e.relations as r}<li><a href={"/e/" + encodeURIComponent(r.from.id)} class={r.from.id === e.id ? "text-dim" : "hover:text-brand"}>{r.from.label}</a> <span class="text-dim">{r.surface || r.predicate}</span> <a href={"/e/" + encodeURIComponent(r.to.id)} class={r.to.id === e.id ? "text-dim" : "hover:text-brand"}>{r.to.label}</a> <span class="num text-[10px] text-dim">{r.predicate} · {r.stance} · {day(r.when)}</span>{#if r.quotes?.length}<div class="text-xs text-dim">“{r.quotes.at(-1).quote}”</div>{/if}</li>{/each}</ul></section>{/if}
  {#if e.claims.length}<section><h2 class="mb-1 text-xs font-semibold uppercase tracking-wide text-dim">Stated facts, as observed</h2><table class="text-xs"><tbody>{#each e.claims as c}<tr><td class="num pr-2 text-dim">{c.field}</td><td class="pr-2">{c.value}</td><td class="num pr-2 text-dim">{day(c.validFrom)}{c.validTo ? " → " + day(c.validTo) : ""}</td><td class="text-dim">{c.source}</td></tr>{/each}</tbody></table></section>{/if}
  <section><h2 class="mb-1 text-xs font-semibold uppercase tracking-wide text-dim">Sources</h2><ul class="space-y-2 text-sm">{#each e.sources as s}<li><a href={s.url} target="_blank" rel="noopener" class="text-brand">{s.title}</a> <span class="num text-xs text-dim">{s.source} · {day(s.published)}</span> <a href={"/doc/" + s.content} class="text-xs text-dim hover:text-brand">reading</a>{#if s.quote}<div class="text-xs text-dim">“{s.quote}”</div>{/if}</li>{/each}</ul></section>
</article>
{/if}
